// AgentServiceServer is the server API for AgentService service.
// All implementations must embed UnimplementedAgentServiceServer
// for forward compatibility.
//
// Agent：Momoko 作为 ACP（Agent Client Protocol）客户端，在服务器上启动并控制 Claude Code、Codex 等 Agent。
// 会话里的对话事件走 WebSocket（/api/v1/agent/ws），这里只有一元接口；发起一轮的接口立刻返回。
type AgentServiceServer interface {
	// —— 选择器 ——
	// 新会话 / 会话里 / 工作区默认值用的选项：每个 Agent 的供应商、模型、推理强度和权限模式
	GetAgentOptions(context.Context, *GetAgentOptionsRequest) (*GetAgentOptionsResponse, error)
	// 各管理标签的数量：自己的会话、工作区、MCP、技能，加上大家共用的供应商、运行时、通知
	GetAgentOverview(context.Context, *GetAgentOverviewRequest) (*GetAgentOverviewResponse, error)
	// —— 会话 ——
	// 会话栏：我的未归档会话，按工作区分层
	GetAgentSidebar(context.Context, *GetAgentSidebarRequest) (*GetAgentSidebarResponse, error)
	// 会话列表（管理页）：状态筛选、标题搜索、分页，都在 SQL 里完成；只有自己的，all 为 true 时是所有人的（Agent 管理页）
	ListAgentSessions(context.Context, *ListAgentSessionsRequest) (*ListAgentSessionsResponse, error)
	// 新建会话并发出第一条消息
	CreateAgentSession(context.Context, *CreateAgentSessionRequest) (*CreateAgentSessionResponse, error)
	GetAgentSession(context.Context, *GetAgentSessionRequest) (*GetAgentSessionResponse, error)
	// 会话的 Agent 进程（命令、进程号、内存、已运行），展开看时才读
	GetAgentSessionProcess(context.Context, *GetAgentSessionProcessRequest) (*GetAgentSessionProcessResponse, error)
	// 发一条消息，开始新的一轮；立刻返回，后续靠 WebSocket
	PromptAgentSession(context.Context, *PromptAgentSessionRequest) (*PromptAgentSessionResponse, error)
	// 停止当前这一轮
	CancelAgentSession(context.Context, *CancelAgentSessionRequest) (*CancelAgentSessionResponse, error)
	// 撤回一条排着队的消息（还没发出去的）
	DeleteAgentQueuedPrompt(context.Context, *DeleteAgentQueuedPromptRequest) (*DeleteAgentQueuedPromptResponse, error)
	// 排着队的一条马上发：能插进正在跑的一轮就插进去（ACP v2）；插不进去的停下这一轮，让它作为下一轮发出
	SendAgentQueuedPrompt(context.Context, *SendAgentQueuedPromptRequest) (*SendAgentQueuedPromptResponse, error)
	// 只停一项（ACP v2，它声明了能单独停时）：一个工具调用，或者一个子 Agent
	StopAgentSessionItem(context.Context, *StopAgentSessionItemRequest) (*StopAgentSessionItemResponse, error)
	// 回答批准卡片
	ResolveAgentPermission(context.Context, *ResolveAgentPermissionRequest) (*ResolveAgentPermissionResponse, error)
	// 切换权限模式 / 模型 / 推理强度
	SetAgentSessionOption(context.Context, *SetAgentSessionOptionRequest) (*SetAgentSessionOptionResponse, error)
	RenameAgentSession(context.Context, *RenameAgentSessionRequest) (*RenameAgentSessionResponse, error)
	// 复刻对话；worktree 为 true 时放到自动命名的新工作树里
	ForkAgentSession(context.Context, *ForkAgentSessionRequest) (*ForkAgentSessionResponse, error)
	// 把复刻出来的会话移到外层
	DetachAgentSession(context.Context, *DetachAgentSessionRequest) (*DetachAgentSessionResponse, error)
	// 归档 / 取消归档（还在运行或等待批准的不能归档）
	ArchiveAgentSessions(context.Context, *ArchiveAgentSessionsRequest) (*ArchiveAgentSessionsResponse, error)
	DeleteAgentSessions(context.Context, *DeleteAgentSessionsRequest) (*DeleteAgentSessionsResponse, error)
	// 删除全部归档会话
	PurgeAgentSessions(context.Context, *PurgeAgentSessionsRequest) (*PurgeAgentSessionsResponse, error)
	// 导出记录：返回会话的全部事件，由页面排版成 Markdown 下载
	ExportAgentSessions(context.Context, *ExportAgentSessionsRequest) (*ExportAgentSessionsResponse, error)
	// 右侧「改动」：会话目录相对当前分支的未提交改动
	GetAgentSessionChanges(context.Context, *GetAgentSessionChangesRequest) (*GetAgentSessionChangesResponse, error)
	// 撤销某个文件的改动
	RevertAgentSessionFile(context.Context, *RevertAgentSessionFileRequest) (*RevertAgentSessionFileResponse, error)
	// 右侧「文件」：按目录懒加载
	ListAgentSessionFiles(context.Context, *ListAgentSessionFilesRequest) (*ListAgentSessionFilesResponse, error)
	// 打开文件（只读）
	ReadAgentSessionFile(context.Context, *ReadAgentSessionFileRequest) (*ReadAgentSessionFileResponse, error)
	// 取回消息里上传过的附件（显示图片）
	GetAgentSessionUpload(context.Context, *GetAgentSessionUploadRequest) (*GetAgentSessionUploadResponse, error)
	// @ 引用文件：按文件名搜索会话目录（新会话还没有会话时按工作区搜）
	SearchAgentFiles(context.Context, *SearchAgentFilesRequest) (*SearchAgentFilesResponse, error)
	// —— 文件树里的编辑：有会话按会话目录，新会话页还没有会话时按工作区（和 @ 搜索一样给 session_id 或 workspace_id）——
	// 保存文本文件：编辑后保存，或者新建一个文件
	SaveAgentFile(context.Context, *SaveAgentFileRequest) (*SaveAgentFileResponse, error)
	// 新建文件夹
	CreateAgentDir(context.Context, *CreateAgentDirRequest) (*CreateAgentDirResponse, error)
	// 改名或挪到另一个文件夹
	MoveAgentFile(context.Context, *MoveAgentFileRequest) (*MoveAgentFileResponse, error)
	// 删除文件或文件夹（整个删掉，不进回收站）
	DeleteAgentFiles(context.Context, *DeleteAgentFilesRequest) (*DeleteAgentFilesResponse, error)
	// 原样读一个文件（预览图片，Markdown 里用到的图片）
	GetAgentFileRaw(context.Context, *GetAgentFileRawRequest) (*GetAgentSessionUploadResponse, error)
	// HTML 预览的签名：iframe 按 /api/v1/public/agent/preview/{节点}/{签名}/{相对路径} 把目录当静态站点加载
	GetAgentPreviewToken(context.Context, *GetAgentPreviewTokenRequest) (*GetAgentPreviewTokenResponse, error)
	// —— 工作区 ——
	ListAgentWorkspaces(context.Context, *ListAgentWorkspacesRequest) (*ListAgentWorkspacesResponse, error)
	CreateAgentWorkspace(context.Context, *CreateAgentWorkspaceRequest) (*CreateAgentWorkspaceResponse, error)
	UpdateAgentWorkspace(context.Context, *UpdateAgentWorkspaceRequest) (*UpdateAgentWorkspaceResponse, error)
	// 移除工作区：只删记录，目录里的文件不动
	DeleteAgentWorkspace(context.Context, *DeleteAgentWorkspaceRequest) (*DeleteAgentWorkspaceResponse, error)
	// 「浏览」：列出服务器上某个目录下的子目录
	ListAgentDirs(context.Context, *ListAgentDirsRequest) (*ListAgentDirsResponse, error)
	// 「查看文件」：只读地列出工作区里的目录和文件
	BrowseAgentWorkspace(context.Context, *BrowseAgentWorkspaceRequest) (*BrowseAgentWorkspaceResponse, error)
	// 新会话页里打开工作区的文件（只读，和会话里打开文件一样的返回）
	ReadAgentWorkspaceFile(context.Context, *ReadAgentWorkspaceFileRequest) (*ReadAgentSessionFileResponse, error)
	// 项目指令文件（AGENTS.md / CLAUDE.md）；按目录读，新建工作区时目录还没有记录
	GetAgentDocs(context.Context, *GetAgentDocsRequest) (*GetAgentDocsResponse, error)
	// —— 模型供应商（第三方接口）：每个人自己的，加上管理员共享给他的 ——
	ListAgentProviders(context.Context, *ListAgentProvidersRequest) (*ListAgentProvidersResponse, error)
	// 第三方接口
	CreateAgentProvider(context.Context, *CreateAgentProviderRequest) (*CreateAgentProviderResponse, error)
	UpdateAgentProvider(context.Context, *UpdateAgentProviderRequest) (*UpdateAgentProviderResponse, error)
	DeleteAgentProvider(context.Context, *DeleteAgentProviderRequest) (*DeleteAgentProviderResponse, error)
	// 测试：用主模型发一条消息，供应商给的每种协议各发一次。有草稿测草稿（地址、密钥留空且有 id 时用已保存的），否则测已保存的
	TestAgentProvider(context.Context, *TestAgentProviderRequest) (*TestAgentProviderResponse, error)
	// 获取可用模型
	FetchAgentProviderModels(context.Context, *FetchAgentProviderModelsRequest) (*FetchAgentProviderModelsResponse, error)
	// 账户余额：只有能查余额的供应商类型（AgentVendor.balance）才有
	GetAgentProviderBalance(context.Context, *GetAgentProviderBalanceRequest) (*GetAgentProviderBalanceResponse, error)
	// —— MCP ——
	ListAgentMcpServers(context.Context, *ListAgentMcpServersRequest) (*ListAgentMcpServersResponse, error)
	CreateAgentMcpServer(context.Context, *CreateAgentMcpServerRequest) (*CreateAgentMcpServerResponse, error)
	UpdateAgentMcpServer(context.Context, *UpdateAgentMcpServerRequest) (*UpdateAgentMcpServerResponse, error)
	DeleteAgentMcpServer(context.Context, *DeleteAgentMcpServerRequest) (*DeleteAgentMcpServerResponse, error)
	// 新会话默认开启的开关
	SetAgentMcpDefault(context.Context, *SetAgentMcpDefaultRequest) (*SetAgentMcpDefaultResponse, error)
	// 测试连接：由 Momoko 自己连一次，读它的工具列表
	TestAgentMcpServer(context.Context, *TestAgentMcpServerRequest) (*TestAgentMcpServerResponse, error)
	// 粘贴 mcpServers JSON 导入
	ImportAgentMcpServers(context.Context, *ImportAgentMcpServersRequest) (*ImportAgentMcpServersResponse, error)
	// —— 技能 ——
	ListAgentSkills(context.Context, *ListAgentSkillsRequest) (*ListAgentSkillsResponse, error)
	GetAgentSkill(context.Context, *GetAgentSkillRequest) (*GetAgentSkillResponse, error)
	CreateAgentSkill(context.Context, *CreateAgentSkillRequest) (*CreateAgentSkillResponse, error)
	UpdateAgentSkill(context.Context, *UpdateAgentSkillRequest) (*UpdateAgentSkillResponse, error)
	DeleteAgentSkill(context.Context, *DeleteAgentSkillRequest) (*DeleteAgentSkillResponse, error)
	SetAgentSkillEnabled(context.Context, *SetAgentSkillEnabledRequest) (*SetAgentSkillEnabledResponse, error)
	// 导入：压缩包（zip 内容）、Git 地址、服务器上已有的目录
	ImportAgentSkill(context.Context, *ImportAgentSkillRequest) (*ImportAgentSkillResponse, error)
	// Agent 管理页给共享的 MCP、技能选人用：所有用户的名称（要有 agent:admin）
	ListAgentUsers(context.Context, *ListAgentUsersRequest) (*ListAgentUsersResponse, error)
	// —— 运行时 ——
	ListAgentRuntimes(context.Context, *ListAgentRuntimesRequest) (*ListAgentRuntimesResponse, error)
	// 安装方式：Momoko 下载并更新 / 用服务器上已有的命令
	SetAgentRuntimeMode(context.Context, *SetAgentRuntimeModeRequest) (*SetAgentRuntimeModeResponse, error)
	// 重新检测
	DetectAgentRuntime(context.Context, *DetectAgentRuntimeRequest) (*DetectAgentRuntimeResponse, error)
	// 服务器上的登录：给检查时读到的模型设最长上下文和最长输出
	SetAgentRuntimeModels(context.Context, *SetAgentRuntimeModelsRequest) (*SetAgentRuntimeModelsResponse, error)
	// 检查更新；由 Momoko 下载的会直接更新到最新版本
	UpdateAgentRuntime(context.Context, *UpdateAgentRuntimeRequest) (*UpdateAgentRuntimeResponse, error)
	// 添加其它 ACP Agent
	CreateAgentRuntime(context.Context, *CreateAgentRuntimeRequest) (*CreateAgentRuntimeResponse, error)
	DeleteAgentRuntime(context.Context, *DeleteAgentRuntimeRequest) (*DeleteAgentRuntimeResponse, error)
	// 同时运行的进程上限、空闲后结束进程
	UpdateAgentRunSettings(context.Context, *UpdateAgentRunSettingsRequest) (*UpdateAgentRunSettingsResponse, error)
	// —— 通知：每个人自己的 ——
	GetAgentNotify(context.Context, *GetAgentNotifyRequest) (*GetAgentNotifyResponse, error)
	// 三个时机开关
	UpdateAgentNotifyEvents(context.Context, *UpdateAgentNotifyEventsRequest) (*UpdateAgentNotifyEventsResponse, error)
	// 保存某种通知方式的配置，保存后自动启用
	SaveAgentNotifyChannel(context.Context, *SaveAgentNotifyChannelRequest) (*SaveAgentNotifyChannelResponse, error)
	SetAgentNotifyChannelEnabled(context.Context, *SetAgentNotifyChannelEnabledRequest) (*SetAgentNotifyChannelEnabledResponse, error)
	// 移除某种通知方式的配置
	DeleteAgentNotifyChannel(context.Context, *DeleteAgentNotifyChannelRequest) (*DeleteAgentNotifyChannelResponse, error)
	// 所有人的通知设置（Agent 管理页，要有 agent:admin）：只列设置过通知方式的人，密钥只给脱敏值
	ListAgentNotify(context.Context, *ListAgentNotifyRequest) (*ListAgentNotifyResponse, error)
	// 发一条测试；fields 为空时用已保存的配置
	TestAgentNotifyChannel(context.Context, *TestAgentNotifyChannelRequest) (*TestAgentNotifyChannelResponse, error)
	mustEmbedUnimplementedAgentServiceServer()
}

